// Contract check for the zero-residency baseline (issue #3077, epic #3076).
//
// Every containers[] declaration found in cloudflare/* and packages/*
// wrangler.jsonc files — plus the release-pinned BusinessApi declaration
// generated by cloudflare/api/ingress/config.mjs — must map to an owned
// entry in cloudflare/zero-residency/manifest.json. A declaration that is
// always-on by shape (no durable_object scheduling policy and no verifiable
// sleepAfter evidence) fails unless the manifest records it as
// always-on-tracked or retire-under-#1954 with an owner issue.
//
// Runs offline: `cd cloudflare/zero-residency && npx vitest run`.

import { describe, expect, it } from 'vitest'
import { existsSync, readFileSync, readdirSync } from 'node:fs'
import { dirname, join, normalize, relative } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

const HERE = fileURLToPath(new URL('..', import.meta.url))
const ROOT = normalize(join(HERE, '..', '..'))
const MODES = ['on-demand', 'managed', 'retire-under-#1954', 'always-on-tracked', 'event-infra']

const manifest = JSON.parse(readFileSync(join(HERE, 'manifest.json'), 'utf8'))
const baselinePath = join(HERE, manifest.baseline)
const baseline = JSON.parse(readFileSync(baselinePath, 'utf8'))

// The repo's existing wrangler.jsonc reads strip line comments then JSON.parse
// (see scripts/device-gateway/deploy.mjs); block comments are stripped here too.
function parseJsonc(text) {
  return JSON.parse(text.replace(/^\s*\/\/.*$/gm, '').replace(/\/\*[\s\S]*?\*\//g, ''))
}

function wranglerFiles() {
  const files = []
  for (const scope of ['cloudflare', 'packages']) {
    const scopeDir = join(ROOT, scope)
    for (const entry of readdirSync(scopeDir, { withFileTypes: true })) {
      if (!entry.isDirectory()) continue
      const candidate = join(scopeDir, entry.name, 'wrangler.jsonc')
      if (existsSync(candidate)) files.push(join(scope, entry.name, 'wrangler.jsonc'))
    }
  }
  return files.sort()
}

const toRepoPath = (p) => relative(ROOT, normalize(p)).split('\\').join('/')

// All container declarations visible to this repository.
async function collectDeclarations() {
  const declarations = []
  for (const rel of wranglerFiles()) {
    const config = parseJsonc(readFileSync(join(ROOT, rel), 'utf8'))
    for (const container of config.containers ?? []) {
      declarations.push({
        source: rel,
        className: container.class_name ?? null,
        schedulingPolicy: container.scheduling_policy ?? null,
        workerMain: config.main ? join(dirname(rel), config.main) : null,
      })
    }
  }
  // The per-release API applications are generated, not committed as wrangler
  // files; evaluate the generator so the check covers them too.
  const configSource = join(ROOT, 'cloudflare/api/ingress/config.mjs')
  const { ingressConfig } = await import(pathToFileURL(configSource).href)
  const generated = ingressConfig({
    release: 'contractcheck',
    image: 'registry.invalid/mikka-api@sha256:' + '0'.repeat(64),
    origin: 'https://contract.invalid',
  })
  for (const container of generated.containers ?? []) {
    declarations.push({
      source: 'cloudflare/api/ingress/config.mjs',
      className: container.class_name ?? null,
      schedulingPolicy: container.scheduling_policy ?? null,
      workerMain: generated.main ? toRepoPath(generated.main) : null,
    })
  }
  return declarations
}

const globToRegExp = (pattern) =>
  new RegExp('^' + pattern.replace(/[.+?^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*') + '$')

const manifestEntries = manifest.declarations
const findEntry = (decl) =>
  manifestEntries.find((e) => e.source === decl.source && e.className === decl.className)

const declarations = await collectDeclarations()

describe('zero-residency manifest', () => {
  it('declares only known modes with owner issues', () => {
    for (const entry of manifestEntries) {
      expect(MODES, `unknown mode in ${entry.className}`).toContain(entry.mode)
      expect(typeof entry.ownerIssue, `${entry.className} missing ownerIssue`).toBe('number')
    }
  })

  it('points at a readable baseline capture', () => {
    expect(baseline.baseline).toBe('epic3076-cf0-zero-residency')
    expect(Array.isArray(baseline.applications)).toBe(true)
    expect(baseline.applications.length).toBeGreaterThan(0)
  })
})

describe('container declarations', () => {
  it('finds at least the known declarations', () => {
    const classes = declarations.map((d) => `${d.source}::${d.className}`)
    expect(classes).toContain('cloudflare/task-sandbox/wrangler.jsonc::TaskMachine')
    expect(classes).toContain('cloudflare/litellm/wrangler.jsonc::LiteLlm')
    expect(classes).toContain('cloudflare/eve-runtime/wrangler.jsonc::EveRuntime')
    expect(classes).toContain('cloudflare/api/ingress/config.mjs::BusinessApi')
  })

  it.each(declarations.map((d) => [`${d.source}::${d.className}`, d]))(
    '%s maps to an owned manifest entry',
    (_label, decl) => {
      const entry = findEntry(decl)
      expect(entry, `unowned container declaration ${decl.source} class ${decl.className}: add a manifest declarations[] entry with an owner issue`).toBeDefined()
      expect(typeof entry.ownerIssue).toBe('number')
      expect(MODES).toContain(entry.mode)
    },
  )

  it.each(declarations.map((d) => [`${d.source}::${d.className}`, d]))(
    '%s does not introduce unowned always-on residency',
    (_label, decl) => {
      const entry = findEntry(decl)
      if (!entry) return // ownership failure is reported by the sibling check
      if (decl.schedulingPolicy === 'durable_object') {
        expect(entry.mode, `${decl.className} is durable_object-scheduled but not recorded on-demand`).toBe('on-demand')
        return
      }
      // default scheduling policy keeps a provisioned application unless the
      // container class sleeps itself; a bare on-demand claim is not evidence.
      expect(
        entry.mode,
        `${decl.className} claims on-demand without durable_object scheduling policy`,
      ).not.toBe('on-demand')
      if (entry.mode === 'always-on-tracked') {
        expect(
          entry.alwaysOnEvidence && existsSync(join(ROOT, entry.alwaysOnEvidence)),
          `${decl.className} is always-on but alwaysOnEvidence is missing`,
        ).toBe(true)
        return
      }
      const sleepFile = entry.sleepEvidence && join(ROOT, entry.sleepEvidence)
      expect(
        sleepFile && existsSync(sleepFile),
        `${decl.className} is ${entry.mode} but cites no sleepEvidence file`,
      ).toBe(true)
      const worker = readFileSync(sleepFile, 'utf8')
      expect(
        worker.includes(`class ${entry.className}`),
        `${entry.sleepEvidence} does not declare class ${entry.className}`,
      ).toBe(true)
      expect(
        /sleepAfter\s*=/.test(worker),
        `${decl.className} has no durable_object policy and ${entry.sleepEvidence} shows no sleepAfter`,
      ).toBe(true)
    },
  )
})

describe('manifest staleness', () => {
  it.each(manifestEntries.filter((e) => e.generated === false).map((e) => [e.source, e]))(
    'manifest entry %s still has a real containers[] declaration',
    (_label, entry) => {
      const source = join(ROOT, entry.source)
      expect(existsSync(source), `${entry.source} no longer exists`).toBe(true)
      const config = parseJsonc(readFileSync(source, 'utf8'))
      const classes = (config.containers ?? []).map((c) => c.class_name)
      expect(classes, `${entry.source} no longer declares ${entry.className}`).toContain(entry.className)
    },
  )

  it('every baseline application matches an owned appPattern', () => {
    const patterns = manifestEntries.map((e) => ({ pattern: e.appPattern, re: globToRegExp(e.appPattern) }))
    for (const app of baseline.applications) {
      const match = patterns.find((p) => p.re.test(app.name))
      expect(match, `baseline application ${app.name} matches no manifest appPattern`).toBeDefined()
    }
  })

  it('every oracle container is tracked', () => {
    const tracked = new Set(manifest.oracle.containers.map((c) => c.name))
    for (const container of baseline.oracle.alwaysOnContainers) {
      expect(tracked.has(container.name), `oracle container ${container.name} is untracked`).toBe(true)
    }
  })
})
